    /**
     * Method to retrieve the Appointment via AppointmentFetchOneSummary
     * @param 	summary AppointmentFetchOneSummary 
     * @return 	AppointmentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Appointment getAppointment( AppointmentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "AppointmentFetchOneSummary arg cannot be null" );
    	
    	Appointment entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Appointment
        	// --------------------------------------
        	CompletableFuture<Appointment> futureEntity = queryGateway.query(new FindAppointmentQuery( new LoadAppointmentFilter( summary.getAppointmentId() ) ), ResponseTypes.instanceOf(Appointment.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Appointment with id " + summary.getAppointmentId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


